import{_ as a,c as t,o as i,ae as o}from"./chunks/framework.BIhw3mML.js";const p=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),n={name:"en/faq.md"};function s(r,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><h2 id="alert-visibility-and-assignment" tabindex="-1">Alert Visibility and Assignment <a class="header-anchor" href="#alert-visibility-and-assignment" aria-label="Permalink to &quot;Alert Visibility and Assignment&quot;">​</a></h2><h3 id="_1-why-can-t-i-see-a-certain-alert-on-my-homepage" tabindex="-1">1.Why can&#39;t I see a certain alert on my homepage? <a class="header-anchor" href="#_1-why-can-t-i-see-a-certain-alert-on-my-homepage" aria-label="Permalink to &quot;1.Why can&#39;t I see a certain alert on my homepage?&quot;">​</a></h3><p>The alert has not been assigned to you. Please confirm whether the associated work order or project falls within your responsibility scope.</p><h3 id="_2-can-a-single-alert-be-assigned-to-multiple-people-for-handling" tabindex="-1">2.Can a single alert be assigned to multiple people for handling? <a class="header-anchor" href="#_2-can-a-single-alert-be-assigned-to-multiple-people-for-handling" aria-label="Permalink to &quot;2.Can a single alert be assigned to multiple people for handling?&quot;">​</a></h3><p>No. Each alert is assigned to one primary responsible person to ensure clear accountability. For collaboration, you may @ relevant colleagues in the action item description or upload communication records as attachments.</p><h3 id="_3-can-an-application-owner-review-alerts-on-behalf-of-the-recipient" tabindex="-1">3.Can an Application Owner review alerts on behalf of the recipient? <a class="header-anchor" href="#_3-can-an-application-owner-review-alerts-on-behalf-of-the-recipient" aria-label="Permalink to &quot;3.Can an Application Owner review alerts on behalf of the recipient?&quot;">​</a></h3><p>Not recommended. The system follows the principle of “who receives, who reviews” to maintain clear ownership.</p><h2 id="processing-workflow-and-status" tabindex="-1">Processing Workflow and Status <a class="header-anchor" href="#processing-workflow-and-status" aria-label="Permalink to &quot;Processing Workflow and Status&quot;">​</a></h2><h3 id="_1-what-if-i-selected-the-wrong-processing-method-for-an-alert—can-it-be-changed" tabindex="-1">1.What if I selected the wrong processing method for an alert—can it be changed? <a class="header-anchor" href="#_1-what-if-i-selected-the-wrong-processing-method-for-an-alert—can-it-be-changed" aria-label="Permalink to &quot;1.What if I selected the wrong processing method for an alert—can it be changed?&quot;">​</a></h3><p>Once submitted, the processing method cannot be modified. If an adjustment is needed, please contact the Application Owner to initiate a correction process.</p><h3 id="_2-what-are-the-alert-statuses-and-what-do-they-mean" tabindex="-1">2.What are the alert statuses, and what do they mean? <a class="header-anchor" href="#_2-what-are-the-alert-statuses-and-what-do-they-mean" aria-label="Permalink to &quot;2.What are the alert statuses, and what do they mean?&quot;">​</a></h3><p>Main statuses include:</p><ul><li><strong>Suspected Issue</strong>: AI has detected a risk; pending recipient confirmation</li><li><strong>Issue</strong>: Issue is valid and awaiting resolution</li><li><strong>Closed</strong>: Issue is invalid or already resolved (via “Close with Additional Information”)</li></ul><h3 id="_3-what-is-the-relationship-between-alerts-and-action-items" tabindex="-1">3.What is the relationship between alerts and action items? <a class="header-anchor" href="#_3-what-is-the-relationship-between-alerts-and-action-items" aria-label="Permalink to &quot;3.What is the relationship between alerts and action items?&quot;">​</a></h3><p>When an alert is confirmed as a valid issue requiring corrective action, you can create a dedicated task by selecting “Add Action Item,” assign a responsible person, and set a completion deadline. Action items are tracked independently to ensure closed-loop resolution.</p><h3 id="_4-how-should-i-handle-cases-where-ai-misjudges-a-normal-image-document-as-abnormal" tabindex="-1">4.How should I handle cases where AI misjudges a normal image/document as abnormal? <a class="header-anchor" href="#_4-how-should-i-handle-cases-where-ai-misjudges-a-normal-image-document-as-abnormal" aria-label="Permalink to &quot;4.How should I handle cases where AI misjudges a normal image/document as abnormal?&quot;">​</a></h3><p>Select the “Close with Additional Information” option, explain the actual situation in the confirmation description, and optionally upload supporting evidence (e.g., original files or communication records) to help improve the model.</p><h3 id="_5-will-the-system-automatically-close-overdue-alerts" tabindex="-1">5.Will the system automatically close overdue alerts? <a class="header-anchor" href="#_5-will-the-system-automatically-close-overdue-alerts" aria-label="Permalink to &quot;5.Will the system automatically close overdue alerts?&quot;">​</a></h3><p>No. All alerts require manual review and confirmation. We recommend regularly checking 【Pending Confirmation Alerts】 to avoid missing any items.</p><h3 id="_6-what-happens-if-an-action-item-is-not-completed-by-its-due-date" tabindex="-1">6.What happens if an action item is not completed by its due date? <a class="header-anchor" href="#_6-what-happens-if-an-action-item-is-not-completed-by-its-due-date" aria-label="Permalink to &quot;6.What happens if an action item is not completed by its due date?&quot;">​</a></h3><p>The system will continue to remind the responsible person on their homepage and may trigger escalation mechanisms (e.g., notifying supervisors or Compliance Committee members).</p><h3 id="_7-can-i-edit-the-confirmation-description-or-attachments-after-submission" tabindex="-1">7.Can I edit the confirmation description or attachments after submission? <a class="header-anchor" href="#_7-can-i-edit-the-confirmation-description-or-attachments-after-submission" aria-label="Permalink to &quot;7.Can I edit the confirmation description or attachments after submission?&quot;">​</a></h3><p>No direct edits are allowed. If corrections are necessary, please contact the Application Owner.</p><h2 id="permissions-and-data-management" tabindex="-1">Permissions and Data Management <a class="header-anchor" href="#permissions-and-data-management" aria-label="Permalink to &quot;Permissions and Data Management&quot;">​</a></h2><h3 id="_1-how-do-i-request-access-to-the-【alert-application-center】" tabindex="-1">1.How do I request access to the 【Alert Application Center】? <a class="header-anchor" href="#_1-how-do-i-request-access-to-the-【alert-application-center】" aria-label="Permalink to &quot;1.How do I request access to the 【Alert Application Center】?&quot;">​</a></h3><p>Please contact your system administrator and provide role verification (e.g., regional assignment or job responsibilities).</p><h3 id="_2-is-bulk-export-of-alerts-or-action-items-supported" tabindex="-1">2.Is bulk export of alerts or action items supported? <a class="header-anchor" href="#_2-is-bulk-export-of-alerts-or-action-items-supported" aria-label="Permalink to &quot;2.Is bulk export of alerts or action items supported?&quot;">​</a></h3><p>Only Application Owners can export data in Excel or CSV format via 【Alert Application Center】 → corresponding sub-application. Alert recipients do not have this permission.</p><h3 id="_3-what-file-types-are-supported-for-attachments-and-are-there-size-limits" tabindex="-1">3.What file types are supported for attachments, and are there size limits? <a class="header-anchor" href="#_3-what-file-types-are-supported-for-attachments-and-are-there-size-limits" aria-label="Permalink to &quot;3.What file types are supported for attachments, and are there size limits?&quot;">​</a></h3><p>Attachments support multiple file uploads (JPG, PNG, PDF, DOCX, etc.), with a maximum size of 20MB per file. All submitted content—including processing method, descriptions, and attachments—is permanently recorded for audit traceability.</p><h2 id="ai-model-and-detection-logic" tabindex="-1">AI Model and Detection Logic <a class="header-anchor" href="#ai-model-and-detection-logic" aria-label="Permalink to &quot;AI Model and Detection Logic&quot;">​</a></h2><h3 id="_1-what-is-the-difference-between-ai-cts-and-ai-ctq-in-image-detection" tabindex="-1">1.What is the difference between “AI-CTS” and “AI-CTQ” in image detection? <a class="header-anchor" href="#_1-what-is-the-difference-between-ai-cts-and-ai-ctq-in-image-detection" aria-label="Permalink to &quot;1.What is the difference between “AI-CTS” and “AI-CTQ” in image detection?&quot;">​</a></h3><ul><li><strong>CTQ</strong> (Critical to Quality): Focuses on product quality critical points</li><li><strong>CTS</strong> (Critical to Safety): Focuses on personnel/environment safety critical points</li></ul><h3 id="_2-why-aren-t-some-work-steps-triggering-ai-detection" tabindex="-1">2.Why aren’t some work steps triggering AI detection? <a class="header-anchor" href="#_2-why-aren-t-some-work-steps-triggering-ai-detection" aria-label="Permalink to &quot;2.Why aren’t some work steps triggering AI detection?&quot;">​</a></h3><p>AI detection only applies to work steps configured with critical control points (CTQ/CTS). If a step is not covered, please contact your business AI project owner to evaluate inclusion in the monitoring scope.</p><h3 id="_3-how-often-is-the-ai-model-updated-and-how-can-i-report-misjudgments" tabindex="-1">3.How often is the AI model updated, and how can I report misjudgments? <a class="header-anchor" href="#_3-how-often-is-the-ai-model-updated-and-how-can-i-report-misjudgments" aria-label="Permalink to &quot;3.How often is the AI model updated, and how can I report misjudgments?&quot;">​</a></h3><p>Models are iteratively optimized on a quarterly basis. For frequent misjudgments, use “Close with Additional Information” to submit real samples and explanations—the system will automatically collect them for model training.</p><h3 id="_4-will-uploaded-images-documents-be-used-by-ai-for-other-purposes" tabindex="-1">4.Will uploaded images/documents be used by AI for other purposes? <a class="header-anchor" href="#_4-will-uploaded-images-documents-be-used-by-ai-for-other-purposes" aria-label="Permalink to &quot;4.Will uploaded images/documents be used by AI for other purposes?&quot;">​</a></h3><p>No. All data is used solely for risk identification and compliance closure of the current work order, in strict compliance with company data privacy and information security policies. It will not be used for external training or commercial purposes.</p><h3 id="_5-if-a-single-work-order-contains-multiple-anomalies-will-multiple-alerts-be-generated" tabindex="-1">5.If a single work order contains multiple anomalies, will multiple alerts be generated? <a class="header-anchor" href="#_5-if-a-single-work-order-contains-multiple-anomalies-will-multiple-alerts-be-generated" aria-label="Permalink to &quot;5.If a single work order contains multiple anomalies, will multiple alerts be generated?&quot;">​</a></h3><p>Yes. AI splits anomalies by type and location into separate alert items to enable granular confirmation and handling, reducing the risk of oversight.</p><h2 id="system-features-and-limitations" tabindex="-1">System Features and Limitations <a class="header-anchor" href="#system-features-and-limitations" aria-label="Permalink to &quot;System Features and Limitations&quot;">​</a></h2><h3 id="_1-does-the-system-support-a-multilingual-interface" tabindex="-1">1.Does the system support a multilingual interface? <a class="header-anchor" href="#_1-does-the-system-support-a-multilingual-interface" aria-label="Permalink to &quot;1.Does the system support a multilingual interface?&quot;">​</a></h3><p>The interface language automatically matches your browser or system settings (Chinese/English). Alert content (e.g., step descriptions, filenames) remains in its original language to ensure accuracy.</p>',45)])])}const u=a(n,[["render",s]]);export{p as __pageData,u as default};
